        model_line = (f"{html.escape(str(llm.get('model')))} · {html.escape(str(llm.get('quality')))} prompt · "
                      f"{llm.get('input_tokens',0):,}/{llm.get('output_tokens',0):,} tok · {cost}/fix · "
                      f"neatlogs {'on' if llm.get('neatlogs') else 'off'}")
