import html
import json
import os
import sys

PHASE_ICON = {
    "intake": "•", "baseline_tests": "▶", "inspect_code": "👁",
    "propose_patch": "✎", "apply_in_worktree": "±", "apply_failed": "✖",
    "verify": "✔", "classify_failure": "↩", "export_report": "✅",
    "human_review": "⚑",
}


def pick_report(arg):
    if arg:
        return os.path.join("artifacts", arg, "report.json")
    reports = glob.glob("artifacts/*/report.json")
    if not reports:
        sys.exit("no runs in artifacts/. Run: python run_case.py")
    return max(reports, key=os.path.getmtime)


def row_class(phase, detail):
    if phase == "classify_failure":
        return "recover"
    if phase == "verify" and "regressed" in detail:
        return "warn-row"
    if phase == "verify" and "fixed" in detail:
        return "ok-row"
    if phase in ("export_report",):
        return "ok-row"
    if phase in ("apply_failed", "human_review"):
        return "err-row"
    return ""


def main():
    rp = pick_report(sys.argv[1] if len(sys.argv) > 1 else None)
    d = json.load(open(rp, encoding="utf-8"))
    run_dir = os.path.dirname(rp)
    diff = ""
    dp = os.path.join(run_dir, "patch.diff")
    if os.path.exists(dp):
        diff = open(dp, encoding="utf-8").read()

    v = d.get("verdict") or {}
    llm = d.get("llm")
    fixed = d["status"] == "fixed"

    timeline = []
    for e in d["events"]:
        ph, dt = e["phase"], e.get("detail", "")
        icon = PHASE_ICON.get(ph, "•")
        extra = " — recovery: reverted the regressing patch" if ph == "classify_failure" else ""
        timeline.append(
            f'<li class="{row_class(ph, dt)}"><span class="ic">{icon}</span>'
            f'<span class="ph">{html.escape(ph)}</span>'
            f'<span class="dt">{html.escape(dt)}{extra}</span></li>'
        )

    sec = "✅ pass" if v.get("security_pass") else "❌ fail"
    fun = "✅ pass" if v.get("functionality_pass") else "❌ fail"
    regressed = v.get("regressions") or []
    llm_rows = ""
    if llm:
        cost = f"${llm['cost_usd']:.4f}" if llm.get("cost_usd") is not None else "—"
        llm_rows = (f"<tr><td>Model</td><td>{html.escape(str(llm.get('model')))}</td></tr>"
                    f"<tr><td>Prompt quality</td><td>{html.escape(str(llm.get('quality')))}</td></tr>"
                    f"<tr><td>Tokens (in/out)</td><td>{llm.get('input_tokens',0):,} / {llm.get('output_tokens',0):,}</td></tr>"
                    f"<tr><td>Cost per fix</td><td>{cost}</td></tr>"
                    f"<tr><td>neatlogs traced</td><td>{llm.get('neatlogs')}</td></tr>")
    else:
        llm_rows = '<tr><td>Brain</td><td>offline-scripted (no LLM) — token/cost from the live run</td></tr>'

    doc = f"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>TenantGuard Report</title>
<style>
:root{{--bg:#f6f7f9;--fg:#15181e;--muted:#5b6472;--card:#fff;--line:#e3e6eb;
--ok:#0f9d58;--bad:#d93025;--warn:#b36b00;--accent:#4f46e5;--code:#eef0f4;}}
@media(prefers-color-scheme:dark){{:root:not([data-theme=light]){{
--bg:#0e1014;--fg:#e7e9ee;--muted:#9aa4b2;--card:#161920;--line:#262a33;
--ok:#39d98a;--bad:#ff6b6b;--warn:#ffb259;--accent:#8b85ff;--code:#1c2029;}}}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--fg);
font:15px/1.55 -apple-system,Segoe UI,Roboto,sans-serif;padding:24px 16px}}
.wrap{{max-width:860px;margin:0 auto}}h1{{margin:0 0 2px;font-size:25px}}
.lead{{color:var(--muted);margin:0 0 18px}}
.pill{{display:inline-block;font-weight:700;font-size:12px;padding:4px 12px;border-radius:999px}}
.pill.ok{{background:color-mix(in srgb,var(--ok) 18%,transparent);color:var(--ok)}}
.pill.bad{{background:color-mix(in srgb,var(--bad) 18%,transparent);color:var(--bad)}}
.cards{{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:16px 0}}
@media(max-width:620px){{.cards{{grid-template-columns:1fr}}}}
.card{{background:var(--card);border:1px solid var(--line);border-radius:13px;padding:14px}}
.card h3{{margin:0 0 8px;font-size:15px}}
table{{width:100%;border-collapse:collapse;font-size:13px}}
td{{padding:5px 6px;border-bottom:1px solid var(--line)}}td:last-child{{text-align:right}}
h2{{font-size:17px;margin:24px 0 10px}}
ul.tl{{list-style:none;margin:0;padding:0;border:1px solid var(--line);border-radius:12px;overflow:hidden}}
ul.tl li{{display:flex;gap:10px;align-items:center;padding:7px 12px;border-bottom:1px solid var(--line);font-size:13px}}
ul.tl li:last-child{{border-bottom:0}}
.ic{{width:18px;text-align:center}}.ph{{width:150px;font-weight:600}}.dt{{color:var(--muted)}}
li.recover{{background:color-mix(in srgb,var(--warn) 15%,transparent)}}
li.recover .dt{{color:var(--warn);font-weight:600}}
li.warn-row{{background:color-mix(in srgb,var(--warn) 10%,transparent)}}
li.ok-row{{background:color-mix(in srgb,var(--ok) 12%,transparent)}}
li.err-row{{background:color-mix(in srgb,var(--bad) 12%,transparent)}}
pre{{background:var(--code);border:1px solid var(--line);border-radius:10px;padding:12px;overflow:auto;font-size:12px}}
.foot{{color:var(--muted);font-size:12px;margin-top:26px}}
.ins{{color:var(--ok)}}.del{{color:var(--bad)}}
</style></head><body><div class="wrap">
<h1>🛡️ TenantGuard — remediation report</h1>
<p class="lead">neatHack 2026 · team AI LONE STAR · case <code>{html.escape(d['case_id'])}</code></p>
<span class="pill {'ok' if fixed else 'bad'}">{'FIXED' if fixed else d['status'].upper()}</span>

<div class="cards">
  <div class="card"><h3>Outcome</h3><table>
    <tr><td>Status</td><td>{html.escape(d['status'])}</td></tr>
    <tr><td>Patch attempts</td><td>{d['attempts']}</td></tr>
    <tr><td>Security tests</td><td>{sec}</td></tr>
    <tr><td>Functionality tests</td><td>{fun}</td></tr>
    <tr><td>Regression during run</td><td>{'yes → recovered' if any('regressed' in e.get('detail','') for e in d['events']) else 'no'}</td></tr>
    <tr><td>Wall time</td><td>{d.get('wall_seconds')}s</td></tr>
  </table></div>
  <div class="card"><h3>Model / cost</h3><table>{llm_rows}</table></div>
</div>

<h2>Phase timeline — the recovery is highlighted</h2>
<ul class="tl">{''.join(timeline)}</ul>

<h2>The patch it applied</h2>
<pre>{_fmt_diff(diff)}</pre>

<p class="foot">Generated by <code>report.py</code> from <code>{html.escape(rp)}</code>.
Security = cross-tenant access denied; Functionality = legitimate same-tenant access preserved.
Both must pass for success.</p>
</div></body></html>"""

    os.makedirs("docs", exist_ok=True)
    out = os.path.join("docs", "report.html")
    open(out, "w", encoding="utf-8").write(doc)
    print(f"wrote {out} (from {rp})")


def _fmt_diff(diff):
    if not diff:
        return "(no diff)"
    lines = []
    for ln in diff.splitlines():
        esc = html.escape(ln)
        if ln.startswith("+") and not ln.startswith("+++"):
            lines.append(f'<span class="ins">{esc}</span>')
        elif ln.startswith("-") and not ln.startswith("---"):
            lines.append(f'<span class="del">{esc}</span>')
        else:
            lines.append(esc)
    return "\n".join(lines)


if __name__ == "__main__":
    main()

