            f"{body_html(d, diff)}\n<script>\n{SCRIPT}\n</script>\n</body>\n</html>\n")


def page_external(d, diff):
    return (f"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n"
            f"<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n"
            f"<title>TenantGuard Dossier</title>\n{HEAD_FONTS}\n"
            f"<link rel=\"stylesheet\" href=\"/styles.css\">\n</head>\n<body>\n"
            f"{body_html(d, diff)}\n<script src=\"/app.js\"></script>\n</body>\n</html>\n")


